cat > UITests/ComposeTests.swift <<'EOF'
import XCTest
final class ComposeTests: XCTestCase {
  func testCompose() throws {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    let goHome = app.buttons["Go Home"]
    if goHome.waitForExistence(timeout: 2) { goHome.tap() }
    let attachment = XCTAttachment(string: app.debugDescription)
    attachment.name = "Bluesky accessibility tree"
    attachment.lifetime = .keepAlways
    add(attachment)
  }
}
EOF
