input.command:
cat > UITests/ComposeTests.swift <<'EOF'
import XCTest
final class ComposeTests: XCTestCase {
  func testCompose() throws {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    let composer = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS[c] %@", "What's up")).firstMatch
    XCTAssertTrue(composer.waitForExistence(timeout: 10))
    composer.tap()
    let tree = XCTAttachment(string: app.debugDescription)
    tree.name = "Composer accessibility tree"
    tree.lifetime = .keepAlways
    add(tree)
    let screenshot = XCTAttachment(screenshot: app.screenshot())
    screenshot.name = "Compose screen"
    screenshot.lifetime = .keepAlways
    add(screenshot)
  }
}
EOF
