import XCTest
final class ComposeTests: XCTestCase {
  func testPublish() throws {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let statusBar = springboard.statusBars.firstMatch
    XCTAssertTrue(statusBar.waitForExistence(timeout: 5), springboard.debugDescription)
    statusBar.coordinate(withOffset: CGVector(dx: 158, dy: 66)).tap()
    let screenshot = XCTAttachment(screenshot: app.screenshot())
    screenshot.name = "After publish tap"
    screenshot.lifetime = .keepAlways
    add(screenshot)
  }
}
EOF
